"use client";

import { useEffect, useState } from "react";

type Addon = { id: string; name: string; description: string | null; price: number; is_active: boolean };
export function VendorListingAddonsManager({ listingId, onChanged }: { listingId: string; onChanged?: () => void }) {
  const [items, setItems] = useState<Addon[]>([]); const [name, setName] = useState(""); const [description, setDescription] = useState(""); const [price, setPrice] = useState(""); const [error, setError] = useState<string | null>(null); const [busy, setBusy] = useState(false);
  const load = async () => { const response = await fetch(`/api/vendors/listings/${listingId}/addons`, { cache: "no-store" }); const data = await response.json(); if (!response.ok) throw new Error(data.error || "Add-ons could not be loaded."); setItems(data.addons ?? []); };
  useEffect(() => { void load().catch((cause) => setError(cause instanceof Error ? cause.message : "Add-ons could not be loaded.")); }, [listingId]);
  const create = async (event: React.FormEvent) => { event.preventDefault(); setBusy(true); setError(null); try { const response = await fetch(`/api/vendors/listings/${listingId}/addons`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ name, description: description || null, price: Math.round(Number(price) * 100) }) }); const data = await response.json(); if (!response.ok) throw new Error(data.error || "Add-on could not be saved."); setName(""); setDescription(""); setPrice(""); await load(); onChanged?.(); } catch (cause) { setError(cause instanceof Error ? cause.message : "Add-on could not be saved."); } finally { setBusy(false); } };
  const remove = async (id: string) => { if (!window.confirm("Remove this optional add-on?")) return; setBusy(true); setError(null); try { const response = await fetch(`/api/vendors/listings/${listingId}/addons`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ id, action: "delete" }) }); const data = await response.json(); if (!response.ok) throw new Error(data.error || "Add-on could not be removed."); await load(); onChanged?.(); } catch (cause) { setError(cause instanceof Error ? cause.message : "Add-on could not be removed."); } finally { setBusy(false); } };
  const input = "w-full rounded-lg border border-[#EAD2B0] bg-white px-3 py-2 text-sm dark:border-[#4D3331] dark:bg-[#1A1211]";
  return <div className="mt-4 space-y-3 rounded-xl bg-[#FFF3E3] p-3 dark:bg-[#1A1211]"><p className="text-xs text-[#7D6B63]">Optional add-on prices are displayed for customers and can be included in a vendor quotation. They are not charged automatically.</p>{error && <p role="alert" className="text-xs text-rose-700">{error}</p>}<form onSubmit={(event) => void create(event)} className="grid gap-2 sm:grid-cols-3"><input required minLength={2} maxLength={160} className={input} value={name} onChange={(event) => setName(event.target.value)} placeholder="Add-on name"/><input type="number" min="0" step="0.01" required className={input} value={price} onChange={(event) => setPrice(event.target.value)} placeholder="Price ₹"/><button disabled={busy} className="rounded-lg bg-[#681B1D] px-3 py-2 text-xs font-semibold text-white disabled:opacity-50">Add option</button><input maxLength={1000} className={`${input} sm:col-span-3`} value={description} onChange={(event) => setDescription(event.target.value)} placeholder="Description (optional)"/></form><ul className="space-y-2">{items.map((item) => <li key={item.id} className="flex items-center justify-between gap-3 rounded-lg border border-[#EAD2B0] p-2 text-xs dark:border-[#4D3331]"><span><b>{item.name}</b> · ₹{(item.price / 100).toLocaleString("en-IN")}{item.description && <span className="block text-[#7D6B63]">{item.description}</span>}</span><button disabled={busy} onClick={() => void remove(item.id)} className="text-rose-700 underline">Remove</button></li>)}</ul></div>;
}
